1	package com.example.starter.slope;
2	
3	import com.example.starter.slope.SlopeRepository.AssessmentRow;
4	import com.example.starter.slope.SlopeRepository.ChainRow;
5	import com.example.starter.slope.SlopeRepository.EvacuationRow;
6	import com.example.starter.slope.SlopeRepository.LateEventRow;
7	import com.example.starter.slope.SlopeRepository.ReadingRow;
8	import com.example.starter.slope.SlopeRepository.ZoneRow;
9	import com.example.starter.slope.dto.ApiDtos.ArchiveRequest;
10	import com.example.starter.slope.dto.ApiDtos.ArchiveResponse;
11	import com.example.starter.slope.dto.ApiDtos.AssessmentInfo;
12	import com.example.starter.slope.dto.ApiDtos.ChainDetailResponse;
13	import com.example.starter.slope.dto.ApiDtos.CreateZoneRequest;
14	import com.example.starter.slope.dto.ApiDtos.EvacuationConfirmRequest;
15	import com.example.starter.slope.dto.ApiDtos.EvacuationConfirmResponse;
16	import com.example.starter.slope.dto.ApiDtos.EvacuationInfo;
17	import com.example.starter.slope.dto.ApiDtos.IngestReadingRequest;
18	import com.example.starter.slope.dto.ApiDtos.LateEventItem;
19	import com.example.starter.slope.dto.ApiDtos.RateCurveResponse;
20	import com.example.starter.slope.dto.ApiDtos.RatePoint;
21	import com.example.starter.slope.dto.ApiDtos.ReadingResponse;
22	import com.example.starter.slope.dto.ApiDtos.ResumptionApplyRequest;
23	import com.example.starter.slope.dto.ApiDtos.ResumptionApplyResponse;
24	import com.example.starter.slope.dto.ApiDtos.ResumptionConfirmRequest;
25	import com.example.starter.slope.dto.ApiDtos.ResumptionConfirmResponse;
26	import com.example.starter.slope.dto.ApiDtos.ZoneResponse;
27	import com.fasterxml.jackson.databind.ObjectMapper;
28	import org.springframework.stereotype.Service;
29	import org.springframework.transaction.annotation.Transactional;
30	
31	import java.time.LocalDateTime;
32	import java.util.List;
33	
34	/**
35	 * 边坡监测业务服务：监测→预警分级→处置→撤人→复工评估→归档。
36	 * 所有写操作在事务内完成，并按“测区行锁→处置链行锁”的顺序加锁，保证同一测区
37	 * 同时刻仅一条执行中处置链、并发预警唯一受理、停产与复工唯一终态。
38	 * 业务时间全部来自请求报文（监测/确认/申请时刻），便于复算与可控时钟测试。
39	 */
40	@Service
41	public class SlopeService {
42	
43	    /** 撤人确认时限：红色预警触发后30分钟（恰满判定为按时）。 */
44	    static final long EVACUATION_LIMIT_MINUTES = 30;
45	
46	    /** 复工评估等待窗口：红色预警触发后24小时（恰满允许申请）。 */
47	    static final long RECOVERY_WINDOW_HOURS = 24;
48	
49	    private static final String STATUS_NORMAL = "NORMAL";
50	    private static final String STATUS_STOPPED = "STOPPED";
51	    private static final String STATUS_LOCKED = "LOCKED";
52	
53	    private static final String LEVEL_YELLOW = "YELLOW";
54	    private static final String LEVEL_RED = "RED";
55	
56	    private static final String CHAIN_EXECUTING = "EXECUTING";
57	    private static final String CHAIN_RESUMED = "RESUMED";
58	    private static final String CHAIN_ARCHIVED = "ARCHIVED";
59	
60	    private static final String ASSESSMENT_APPLIED = "APPLIED";
61	    private static final String ASSESSMENT_APPROVED = "APPROVED";
62	
63	    private static final String CONFIRM_SITE_CHECK = "SITE_CHECK";
64	    private static final String CONFIRM_MONITORING_REVIEW = "MONITORING_REVIEW";
65	
66	    private final SlopeRepository repository;
67	    private final IdempotencyService idempotencyService;
68	    private final ObjectMapper objectMapper;
69	
70	    public SlopeService(SlopeRepository repository, IdempotencyService idempotencyService,
71	                        ObjectMapper objectMapper) {
72	        this.repository = repository;
73	        this.idempotencyService = idempotencyService;
74	        this.objectMapper = objectMapper;
75	    }
76	
77	    /** 创建测区（幂等）。 */
78	    @Transactional
79	    public IdempotencyService.Stored createZone(CreateZoneRequest request) {
80	        return idempotencyService.execute("POST /api/zones", request.requestId(), request, () -> {
81	            repository.findZoneByCode(request.code()).ifPresent(existing -> {
82	                throw ApiException.conflict("ZONE_CODE_EXISTS", "测区编码已存在: " + request.code());
83	            });
84	            long zoneId = repository.insertZone(request.code(), request.name(),
85	                    request.warnHourlyRate(), request.alarmDailyRate(), request.safetyHourlyRate(),
86	                    request.personnelTotal());
87	            return json(201, new ZoneResponse(zoneId, request.code(), STATUS_NORMAL));
88	        });
89	    }
90	
91	    /** 上报雷达读数：去重、乱序归位、速率复算、预警分级（幂等）。 */
92	    @Transactional
93	    public IdempotencyService.Stored ingestReading(long zoneId, IngestReadingRequest request) {
94	        return idempotencyService.execute("POST /api/zones/{zoneId}/readings", request.requestId(),
95	                new ZoneScopedRequest<>(zoneId, request), () -> doIngestReading(zoneId, request));
96	    }
97	
98	    /** 撤人确认：与作业封锁在同一事务内完成；恰满30分钟判定为按时（幂等）。 */
99	    @Transactional
100	    public IdempotencyService.Stored confirmEvacuation(long chainId, EvacuationConfirmRequest request) {
101	        return idempotencyService.execute("POST /api/chains/{chainId}/evacuation-confirmations",
102	                request.requestId(), new ChainScopedRequest<>(chainId, request),
103	                () -> doConfirmEvacuation(chainId, request));
104	    }
105	
106	    /** 复工评估申请：红色预警后连续24小时速率低于安全线，恰满24小时允许（幂等）。 */
107	    @Transactional
108	    public IdempotencyService.Stored applyResumption(long chainId, ResumptionApplyRequest request) {
109	        return idempotencyService.execute("POST /api/chains/{chainId}/resumption-applications",
110	                request.requestId(), new ChainScopedRequest<>(chainId, request),
111	                () -> doApplyResumption(chainId, request));
112	    }
113	
114	    /** 复工双确认：现场核查与监测复核均确认后批准复工（幂等）。 */
115	    @Transactional
116	    public IdempotencyService.Stored confirmResumption(long chainId, ResumptionConfirmRequest request) {
117	        return idempotencyService.execute("POST /api/chains/{chainId}/resumption-confirmations",
118	                request.requestId(), new ChainScopedRequest<>(chainId, request),
119	                () -> doConfirmResumption(chainId, request));
120	    }
121	
122	    /** 归档：终态；重复归档返回幂等成功（幂等）。 */
123	    @Transactional
124	    public IdempotencyService.Stored archiveChain(long chainId, ArchiveRequest request) {
125	        return idempotencyService.execute("POST /api/chains/{chainId}/archive",
126	                request.requestId(), new ChainScopedRequest<>(chainId, request),
127	                () -> doArchiveChain(chainId, request));
128	    }
129	
130	    /** 速率曲线：由位移读数复算。 */
131	    @Transactional(readOnly = true)
132	    public RateCurveResponse rateCurve(long zoneId) {
133	        repository.findZoneById(zoneId).orElseThrow(
134	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
135	        List<RateCalculator.Sample> samples = repository.findReadingsByZone(zoneId).stream()
136	                .map(row -> new RateCalculator.Sample(row.measuredAt(), row.displacementMm()))
137	                .toList();
138	        List<RatePoint> points = RateCalculator.compute(samples).stream()
139	                .map(rated -> new RatePoint(rated.measuredAt(), rated.displacementMm(),
140	                        rated.hourlyRate(), rated.dailyRate()))
141	                .toList();
142	        return new RateCurveResponse(zoneId, points);
143	    }
144	
145	    /** 处置链详情。 */
146	    @Transactional(readOnly = true)
147	    public ChainDetailResponse chainDetail(long chainId) {
148	        ChainRow chain = repository.findChainById(chainId).orElseThrow(
149	                () -> ApiException.notFound("CHAIN_NOT_FOUND", "处置链不存在: " + chainId));
150	        EvacuationInfo evacuation = repository.findEvacuationByChain(chainId)
151	                .map(row -> new EvacuationInfo(row.confirmedAt(), row.arrivedCount(), row.onTime()))
152	                .orElse(null);
153	        AssessmentInfo assessment = repository.findAssessmentByChain(chainId)
154	                .map(row -> new AssessmentInfo(row.id(), row.appliedAt(), row.siteCheckConfirmed(),
155	                        row.monitoringReviewConfirmed(), row.status(), row.approvedAt()))
156	                .orElse(null);
157	        return new ChainDetailResponse(chain.id(), chain.zoneId(), chain.level(), chain.status(),
158	                chain.triggeredAt(), chain.evacuateDeadline(), chain.evacuatedAt(), chain.archivedAt(),
159	                evacuation, assessment);
160	    }
161	
162	    /** 迟到事件列表。 */
163	    @Transactional(readOnly = true)
164	    public List<LateEventItem> lateEvents(long zoneId) {
165	        repository.findZoneById(zoneId).orElseThrow(
166	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
167	        return repository.findLateEventsByZone(zoneId).stream()
168	                .map(row -> new LateEventItem(row.id(), row.chainId(), row.measuredAt(),
169	                        row.displacementMm(), row.reason()))
170	                .toList();
171	    }
172	
173	    // ------------------------------------------------------------------
174	    // 以下为事务内业务实现
175	    // ------------------------------------------------------------------
176	
177	    private IdempotencyService.Stored doIngestReading(long zoneId, IngestReadingRequest request) {
178	        ZoneRow zone = repository.findZoneByIdForUpdate(zoneId).orElseThrow(
179	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
180	
181	        // 归档为终态：归档时刻之前（含）的迟到位移只记迟到事件，不进入速率曲线。
182	        var archived = repository.findLatestArchivedChainByZone(zoneId);
183	        if (archived.isPresent() && !request.measuredAt().isAfter(archived.get().archivedAt())) {
184	            repository.insertLateEvent(zoneId, archived.get().id(), request.measuredAt(),
185	                    request.displacementMm(), "ARCHIVED_LATE_DATA");
186	            return json(201, new ReadingResponse(null, false, true, null, null,
187	                    "NONE", null, zone.status()));
188	        }
189	
190	        // 监测数据按“测区＋时刻”去重。
191	        var duplicated = repository.findReading(zoneId, request.measuredAt());
192	        if (duplicated.isPresent()) {
193	            ReadingRow existing = duplicated.get();
194	            return json(200, new ReadingResponse(existing.id(), true, false,
195	                    existing.hourlyRate(), existing.dailyRate(), "NONE", null, zone.status()));
196	        }
197	
198	        repository.insertReading(zoneId, request.measuredAt(), request.displacementMm());
199	        recomputeZoneRates(zoneId);
200	        ReadingRow reading = repository.findReading(zoneId, request.measuredAt()).orElseThrow();
201	
202	        String evaluation = evaluateAlarm(zone, reading);
203	        Long chainId = repository.findExecutingChainByZone(zoneId).map(ChainRow::id).orElse(null);
204	        ZoneRow current = repository.findZoneById(zoneId).orElseThrow();
205	        return json(201, new ReadingResponse(reading.id(), false, false,
206	                reading.hourlyRate(), reading.dailyRate(), evaluation, chainId, current.status()));
207	    }
208	
209	    /**
210	     * 预警分级：日速率严格超过报警值触发红色预警并立即停产撤人；
211	     * 小时速率严格超过预警值触发黄色预警；恰等阈值判正常。
212	     * 红色链执行中（已停产）的后续读数属于回落监测，不再重复受理预警；
213	     * 黄色链执行中再触发黄色视为并发重复预警，拒绝受理（409）。
214	     */
215	    private String evaluateAlarm(ZoneRow zone, ReadingRow reading) {
216	        boolean red = reading.dailyRate() != null && reading.dailyRate() > zone.alarmDailyRate();
217	        boolean yellow = reading.hourlyRate() != null && reading.hourlyRate() > zone.warnHourlyRate();
218	        var executing = repository.findExecutingChainByZone(zone.id());
219	        if (executing.isEmpty()) {
220	            if (red) {
221	                repository.insertChain(zone.id(), LEVEL_RED, CHAIN_EXECUTING, reading.measuredAt(),
222	                        reading.measuredAt().plusMinutes(EVACUATION_LIMIT_MINUTES));
223	                repository.updateZoneStatus(zone.id(), STATUS_STOPPED);
224	                return "RED_CHAIN_CREATED";
225	            }
226	            if (yellow) {
227	                repository.insertChain(zone.id(), LEVEL_YELLOW, CHAIN_EXECUTING, reading.measuredAt(), null);
228	                return "YELLOW_CHAIN_CREATED";
229	            }
230	            return "NORMAL";
231	        }
232	        ChainRow chain = executing.get();
233	        if (LEVEL_RED.equals(chain.level())) {
234	            return "RED_CHAIN_ACTIVE";
235	        }
236	        if (red) {
237	            repository.upgradeChainToRed(chain.id(), reading.measuredAt(),
238	                    reading.measuredAt().plusMinutes(EVACUATION_LIMIT_MINUTES));
239	            repository.updateZoneStatus(zone.id(), STATUS_STOPPED);
240	            return "CHAIN_UPGRADED_RED";
241	        }
242	        if (yellow) {
243	            throw ApiException.conflict("CHAIN_ALREADY_EXECUTING",
244	                    "测区已存在执行中处置链，本次预警不予受理: chainId=" + chain.id());
245	        }
246	        return "NORMAL";
247	    }
248	
249	    private IdempotencyService.Stored doConfirmEvacuation(long chainId, EvacuationConfirmRequest request) {
250	        ChainRow chain = lockZoneAndChain(chainId);
251	        if (!CHAIN_EXECUTING.equals(chain.status())) {
252	            throw ApiException.conflict("CHAIN_NOT_EXECUTING", "处置链不在执行中，无法确认撤人: " + chainId);
253	        }
254	        if (!LEVEL_RED.equals(chain.level())) {
255	            throw ApiException.unprocessable("NOT_RED_CHAIN", "黄色预警无需停产撤人: " + chainId);
256	        }
257	        if (chain.evacuatedAt() != null) {
258	            throw ApiException.conflict("EVACUATION_ALREADY_CONFIRMED", "撤人已确认: " + chainId);
259	        }
260	        ZoneRow zone = repository.findZoneById(chain.zoneId()).orElseThrow();
261	        // 恰满30分钟判定为按时：仅严格晚于截止时刻才判超时。
262	        if (request.confirmedAt().isAfter(chain.evacuateDeadline())) {
263	            throw ApiException.unprocessable("EVACUATION_TIMEOUT",
264	                    "撤人确认超过30分钟时限: deadline=" + chain.evacuateDeadline());
265	        }
266	        if (request.arrivedCount() != zone.personnelTotal()) {
267	            throw ApiException.unprocessable("PERSONNEL_INCOMPLETE",
268	                    "撤人未全员到位: arrived=" + request.arrivedCount()
269	                            + ", required=" + zone.personnelTotal());
270	        }
271	        // 撤人确认与作业封锁在同一事务内完成。
272	        long confirmationId = repository.insertEvacuation(chainId, chain.zoneId(),
273	                request.confirmedAt(), request.arrivedCount(), true);
274	        repository.markChainEvacuated(chainId, request.confirmedAt());
275	        repository.updateZoneStatus(chain.zoneId(), STATUS_LOCKED);
276	        return json(201, new EvacuationConfirmResponse(confirmationId, chainId, true, STATUS_LOCKED));
277	    }
278	
279	    private IdempotencyService.Stored doApplyResumption(long chainId, ResumptionApplyRequest request) {
280	        ChainRow chain = lockZoneAndChain(chainId);
281	        if (!CHAIN_EXECUTING.equals(chain.status())) {
282	            throw ApiException.conflict("CHAIN_NOT_EXECUTING", "处置链不在执行中，无法申请复工: " + chainId);
283	        }
284	        if (!LEVEL_RED.equals(chain.level())) {
285	            throw ApiException.unprocessable("NOT_RED_CHAIN", "黄色预警无需复工评估: " + chainId);
286	        }
287	        if (chain.evacuatedAt() == null) {
288	            throw ApiException.unprocessable("EVACUATION_NOT_CONFIRMED", "撤人未确认，无法申请复工: " + chainId);
289	        }
290	        repository.findAssessmentByChain(chainId).ifPresent(existing -> {
291	            throw ApiException.conflict("ASSESSMENT_EXISTS", "复工评估已申请: " + chainId);
292	        });
293	        ZoneRow zone = repository.findZoneById(chain.zoneId()).orElseThrow();
294	        // 恰满24小时允许申请：仅严格早于触发后24小时才拒绝。
295	        LocalDateTime earliest = chain.triggeredAt().plusHours(RECOVERY_WINDOW_HOURS);
296	        if (request.appliedAt().isBefore(earliest)) {
297	            throw ApiException.unprocessable("RECOVERY_WINDOW_TOO_SHORT",
298	                    "红色预警后未满24小时，无法申请复工: earliest=" + earliest);
299	        }
300	        // 连续24小时速率回落至安全线以下：窗口内全部读数小时速率严格低于安全线。
301	        List<ReadingRow> window = repository.findReadingsByZone(chain.zoneId()).stream()
302	                .filter(row -> row.measuredAt().isAfter(chain.triggeredAt())
303	                        && !row.measuredAt().isAfter(request.appliedAt()))
304	                .toList();
305	        if (window.isEmpty()) {
306	            throw ApiException.unprocessable("NO_MONITORING_DATA",
307	                    "预警后窗口内无监测数据，无法证明速率回落: " + chainId);
308	        }
309	        for (ReadingRow row : window) {
310	            if (row.hourlyRate() == null || row.hourlyRate() >= zone.safetyHourlyRate()) {
311	                throw ApiException.unprocessable("RATE_ABOVE_SAFETY_LINE",
312	                        "窗口内存在速率未回落至安全线以下的读数: measuredAt=" + row.measuredAt());
313	            }
314	        }
315	        long assessmentId = repository.insertAssessment(chainId, chain.zoneId(), request.appliedAt());
316	        return json(201, new ResumptionApplyResponse(assessmentId, ASSESSMENT_APPLIED));
317	    }
318	
319	    private IdempotencyService.Stored doConfirmResumption(long chainId, ResumptionConfirmRequest request) {
320	        ChainRow chain = lockZoneAndChain(chainId);
321	        AssessmentRow assessment = repository.findAssessmentByChainForUpdate(chainId).orElseThrow(
322	                () -> ApiException.conflict("ASSESSMENT_NOT_APPLIED", "复工评估未申请: " + chainId));
323	        if (ASSESSMENT_APPROVED.equals(assessment.status())) {
324	            throw ApiException.conflict("RESUMPTION_ALREADY_APPROVED", "复工已批准: " + chainId);
325	        }
326	        String type = request.type();
327	        if (!CONFIRM_SITE_CHECK.equals(type) && !CONFIRM_MONITORING_REVIEW.equals(type)) {
328	            throw ApiException.badRequest("UNKNOWN_CONFIRM_TYPE",
329	                    "确认类型须为SITE_CHECK或MONITORING_REVIEW: " + type);
330	        }
331	        boolean siteCheck = assessment.siteCheckConfirmed();
332	        boolean monitoringReview = assessment.monitoringReviewConfirmed();
333	        if (CONFIRM_SITE_CHECK.equals(type)) {
334	            if (siteCheck) {
335	                throw ApiException.conflict("CONFIRM_DUPLICATED", "现场核查已确认: " + chainId);
336	            }
337	            siteCheck = true;
338	        } else {
339	            if (monitoringReview) {
340	                throw ApiException.conflict("CONFIRM_DUPLICATED", "监测复核已确认: " + chainId);
341	            }
342	            monitoringReview = true;
343	        }
344	        // 双确认齐全才批准复工：停产与复工形成唯一终态。
345	        boolean approved = siteCheck && monitoringReview;
346	        String assessmentStatus = approved ? ASSESSMENT_APPROVED : ASSESSMENT_APPLIED;
347	        repository.updateAssessmentConfirmation(assessment.id(), siteCheck, monitoringReview,
348	                assessmentStatus, approved ? request.confirmedAt() : null);
349	        String chainStatus = chain.status();
350	        String zoneStatus = repository.findZoneById(chain.zoneId()).orElseThrow().status();
351	        if (approved) {
352	            repository.updateChainStatus(chainId, CHAIN_RESUMED, null);
353	            repository.updateZoneStatus(chain.zoneId(), STATUS_NORMAL);
354	            chainStatus = CHAIN_RESUMED;
355	            zoneStatus = STATUS_NORMAL;
356	        }
357	        return json(201, new ResumptionConfirmResponse(assessment.id(), siteCheck, monitoringReview,
358	                assessmentStatus, chainStatus, zoneStatus));
359	    }
360	
361	    private IdempotencyService.Stored doArchiveChain(long chainId, ArchiveRequest request) {
362	        ChainRow chain = lockZoneAndChain(chainId);
363	        if (CHAIN_ARCHIVED.equals(chain.status())) {
364	            // 归档为终态：重复归档返回幂等成功。
365	            return json(200, new ArchiveResponse(chainId, CHAIN_ARCHIVED, chain.archivedAt()));
366	        }
367	        if (CHAIN_EXECUTING.equals(chain.status()) && LEVEL_RED.equals(chain.level())) {
368	            throw ApiException.conflict("CHAIN_NOT_RESUMED", "红色处置链须复工批准后方可归档: " + chainId);
369	        }
370	        repository.updateChainStatus(chainId, CHAIN_ARCHIVED, request.archivedAt());
371	        return json(200, new ArchiveResponse(chainId, CHAIN_ARCHIVED, request.archivedAt()));
372	    }
373	
374	    /**
375	     * 按“测区行锁→处置链行锁”顺序加锁并返回最新链状态。
376	     */
377	    private ChainRow lockZoneAndChain(long chainId) {
378	        ChainRow probe = repository.findChainById(chainId).orElseThrow(
379	                () -> ApiException.notFound("CHAIN_NOT_FOUND", "处置链不存在: " + chainId));
380	        repository.findZoneByIdForUpdate(probe.zoneId()).orElseThrow(
381	                () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + probe.zoneId()));
382	        return repository.findChainByIdForUpdate(chainId).orElseThrow();
383	    }
384	
385	    /**
386	     * 乱序归位后整链复算：按监测时刻重排全部读数并重算速率，保证曲线可复算。
387	     */
388	    private void recomputeZoneRates(long zoneId) {
389	        List<ReadingRow> readings = repository.findReadingsByZone(zoneId);
390	        List<RateCalculator.Sample> samples = readings.stream()
391	                .map(row -> new RateCalculator.Sample(row.measuredAt(), row.displacementMm()))
392	                .toList();
393	        List<RateCalculator.Rated> rated = RateCalculator.compute(samples);
394	        for (int i = 0; i < readings.size(); i++) {
395	            repository.updateReadingRates(readings.get(i).id(),
396	                    rated.get(i).hourlyRate(), rated.get(i).dailyRate());
397	        }
398	    }
