Implementation:

```java
private SafetyWindowEvaluation evaluateSafetyWindow(ZoneRow zone, ChainRow chain, LocalDateTime windowEnd) {
    List<StrategyRow> strategies = repository.findStrategiesByZone(zone.id());
    LocalDateTime windowStart = chain.triggeredAt();
    // 策略变严后不沿用旧安全计时：自变严版本生效时刻重新累计
    for (StrategyRow v : strategies) {
        if (v.effectiveFrom().isAfter(windowStart) && !v.effectiveFrom().isAfter(windowEnd)
                && isStricter(v, predecessorOf(strategies, v), zone)) {
            windowStart = v.effectiveFrom();
        }
    }
    LocalDateTime earliest = windowStart.plusHours(RECOVERY_WINDOW_HOURS);
    if (windowEnd.isBefore(earliest)) {
        throw ApiException.unprocessable("RECOVERY_WINDOW_TOO_SHORT",
                "红色预警后未满24小时安全连续计时，无法申请复工: earliest=" + earliest);
    }
    List<ReadingRow> window = repository.findReadingsByZone(zone.id()).stream()
            .filter(row -> row.measuredAt().isAfter(windowStart) && !row.measuredAt().isAfter(windowEnd))
            .toList();
    if (window.isEmpty()) {
        throw ApiException.unprocessable("NO_MONITORING_DATA", ...);
    }
    List<ReadingJudgment> judgments = new ArrayList<>();
    for (ReadingRow row : window) {
        StrategyRow s = strategyEffectiveAt(strategies, row.measuredAt());
        double effectiveSafety = zone.safetyHourlyRate();
        Integer sv = null; Double rain = null; boolean reduced = false;
        if (s != null) {
            double rainfall = rainfall24hOrThrow(zone.id(), row.measuredAt());
            sv = s.version(); rain = rainfall;
            if (rainfall >= s.rainfall24hThreshold()) {
                effectiveSafety *= s.reductionFactor();
                reduced = true;
            }
        }
        if (row.hourlyRate() == null || row.hourlyRate() >= effectiveSafety) {
            throw ApiException.unprocessable("RATE_ABOVE_SAFETY_LINE", ...);
        }
        judgments.add(new ReadingJudgment(row.measuredAt(), row.hourlyRate(), effectiveSafety, sv, rain, reduced));
    }
    // 评价时刻快照：雨量与策略版本取自同一事务
    StrategyRow atEnd = strategyEffectiveAt(strategies, windowEnd);
    Integer endVersion = null; Double endRain = null; boolean endReduced = false;
    if (atEnd != null) {
        double rainfall = rainfall24hOrThrow(zone.id(), windowEnd);
        endVersion = atEnd.version(); endRain = rainfall;
        endReduced = rainfall >= atEnd.rainfall24hThreshold();
    }
    return new SafetyWindowEvaluation(windowStart, windowEnd, window.size(), endVersion, endRain, endReduced, toJson(judgments));
