private boolean isStricter(StrategyRow candidate, StrategyRow prev, ZoneRow zone) {
    double prevYellow = prev == null ? zone.warnHourlyRate() : prev.yellowHourlyRate();
    double prevRed = prev == null ? zone.alarmDailyRate() : prev.redDailyRate();
    double prevFactor = prev == null ? 1.0 : prev.reductionFactor();
    double prevThreshold = prev == null ? Double.POSITIVE_INFINITY : prev.rainfall24hThreshold();
    return candidate.yellowHourlyRate() < prevYellow
            || candidate.redDailyRate() < prevRed
            || candidate.reductionFactor() < prevFactor
            || candidate.rainfall24hThreshold() < prevThreshold;
}
