effectiveThresholds:
```java
@Transactional(readOnly = true)
public EffectiveThresholdResponse effectiveThresholds(long zoneId, LocalDateTime at) {
    ZoneRow zone = repository.findZoneById(zoneId).orElseThrow(
            () -> ApiException.notFound("ZONE_NOT_FOUND", "测区不存在: " + zoneId));
    StrategyRow s = strategyEffectiveAt(repository.findStrategiesByZone(zoneId), at);
    if (s == null) {
        return new EffectiveThresholdResponse(zoneId, at, null, zone.warnHourlyRate(),
                zone.alarmDailyRate(), zone.safetyHourlyRate(), null, true, false);
    }
    // 同一事务快照：雨量与策略版本一致
    Double rainfall = rainfall24hOrNull(zoneId, at);
    if (rainfall == null) {
        return new EffectiveThresholdResponse(zoneId, at, s.version(), null, null, null, null, false, false);
    }
    boolean reduced = rainfall >= s.rainfall24hThreshold();
    double f = reduced ? s.reductionFactor() : 1.0;
    return new EffectiveThresholdResponse(zoneId, at, s.version(), s.yellowHourlyRate() * f,
            s.redDailyRate() * f, zone.safetyHourlyRate() * f, rainfall, true, reduced);
}
