                    "SELECT status FROM disposal_chain WHERE id = ?", String.class, chainId));
            assertEquals(2, evidence.size());
            assertEquals("APPROVE", evidence.get(1).phase());
        } else {
            // 复核到更正后数据：折减生效，速率1.5不低于安全线1.0，批准被阻断
